  "Retirer l'accès de « {nom} » ? Il faudra le reconnecter depuis Claude.": "Zugriff von „{nom}“ entfernen? Du musst die Verbindung dann von Claude aus neu herstellen.",
  "Retrait impossible": "Entfernen nicht möglich",
  "Applications connectées": "Verbundene Apps",
  "Pour interroger Pécule depuis l'appli Claude (web, ordinateur, iPhone) : dans Claude, Personnaliser → Connecteurs → Ajouter un connecteur personnalisé, avec cette adresse. Pécule te demande alors de te connecter et de choisir entre lecture seule et lecture et actions.": "Um Pécule aus der Claude-App (Web, Computer, iPhone) abzufragen: in Claude Anpassen → Konnektoren → Benutzerdefinierten Konnektor hinzufügen, mit dieser Adresse. Pécule bittet dich dann, dich anzumelden und zwischen „nur Lesen“ und „Lesen und Aktionen“ zu wählen.",
