  "Révoquer « {nom} » ? Le raccourci qui l'utilise ne fonctionnera plus.": "„{nom}“ widerrufen? Der Kurzbefehl, der dieses Token verwendet, funktioniert dann nicht mehr.",
  "Copié": "Kopiert",
  "Raccourci iPhone « Envoyer à Pécule »": "iPhone-Kurzbefehl „An Pécule senden“",
  "Depuis la feuille de partage (Mail, Fichiers, Photos…), envoie un PDF ou une photo : Claude le reconnaît et le range dans Factures ou dans le coffre de documents.": "Sende aus dem Teilen-Menü (Mail, Dateien, Fotos…) ein PDF oder ein Foto: Claude erkennt es und legt es unter Rechnungen oder im Dokumententresor ab.",
  "créé le {date}": "erstellt am {date}",
  "Révoquer": "Widerrufen",
  "Copie ce jeton maintenant : il ne sera plus affiché.": "Kopiere dieses Token jetzt: Es wird nicht noch einmal angezeigt.",
  "Créer un jeton": "Token erstellen",
  "Masquer le mode d'emploi": "Anleitung ausblenden",
  "Mode d'emploi": "Anleitung",
  "App Raccourcis → « + » → nommez le raccourci « Envoyer à Pécule ».": "App „Kurzbefehle“ → „+“ → nenne den Kurzbefehl „An Pécule senden“.",
  "Réglages du raccourci (ⓘ) : activez « Afficher dans la feuille de partage », types acceptés : Fichiers, PDF, Images.": "Einstellungen des Kurzbefehls (ⓘ): aktiviere „Im Share-Sheet anzeigen“, akzeptierte Typen: Dateien, PDFs, Bilder.",
  "Ajoute l'action « Obtenir le contenu de l'URL » :": "Füge die Aktion „Inhalte von URL abrufen“ hinzu:",
  "(après « name= », insérez la variable « Entrée du raccourci → Nom »).": "(füge nach „name=“ die Variable „Kurzbefehleingabe → Name“ ein).",
  "Méthode POST ; en-tête « Authorization » = le jeton copié (« Bearer pec_… ») ; corps de la requête : Fichier → « Entrée du raccourci ».": "Methode POST; Header „Authorization“ = das kopierte Token („Bearer pec_…“); Anfragetext: Datei → „Kurzbefehleingabe“.",
  "Ajoute « Afficher la notification » avec le résultat (titre du document rangé).": "Füge „Mitteilung anzeigen“ mit dem Ergebnis hinzu (Titel des abgelegten Dokuments).",
