  "Oublier ce fait": "Diesen Fakt vergessen",
  "Rien pour l'instant. Dis par exemple à l'assistant « souviens-toi que… » ; il retient aussi de lui-même ce que tu lui expliques (contexte, prélèvements, préférences).": "Noch nichts. Sag dem Assistenten zum Beispiel „Merk dir, dass…“; er merkt sich auch von selbst, was du ihm erklärst (Kontext, Lastschriften, Vorlieben).",
  "Ces faits sont propres à chaque membre et joints aux consignes de l'assistant à chaque conversation.": "Diese Fakten gehören zum jeweiligen Mitglied und werden bei jeder Unterhaltung den Anweisungen des Assistenten beigefügt.",
  "Garde sur cet appareil les dernières données de synthèse (soldes, mois, patrimoine, budget, opérations récentes) 7 jours au plus : l'appli s'ouvre tout de suite, même sans réseau. Effacées à la déconnexion ; jamais les factures, documents ni conversations.": "Speichert die letzten Übersichtsdaten (Salden, Monat, Vermögen, Budget, letzte Buchungen) höchstens 7 Tage auf diesem Gerät: Die App öffnet sich sofort, auch ohne Netz. Beim Abmelden gelöscht; niemals Rechnungen, Dokumente oder Unterhaltungen.",
  "Données effacées de cet appareil": "Daten von diesem Gerät gelöscht",
  "Actif au prochain lancement de l'appli": "Beim nächsten Start der App aktiv",
  "Un nouveau lien remplace l'ancien : les agendas abonnés à l'ancien ne se mettront plus à jour. Continuer ?": "Ein neuer Link ersetzt den alten: Kalender, die den alten abonniert haben, werden nicht mehr aktualisiert. Fortfahren?",
  "Couper l'abonnement ? Les agendas abonnés ne recevront plus l'échéancier.": "Abo beenden? Abonnierte Kalender erhalten den Terminplan dann nicht mehr.",
  "Échéancier dans Calendrier": "Terminplan im Kalender",
  "Abonne Calendrier (iPhone, Mac) à ton échéancier : tâches, mensualités, fins de crédit, garanties, documents qui expirent, calendrier fiscal, avec un rappel la veille. Mis à jour toutes les 6 heures ; le lien est privé, garde-le pour toi.": "Abonniere deinen Terminplan im Kalender (iPhone, Mac): Aufgaben, Monatsraten, Kreditenden, Garantien, ablaufende Dokumente, Steuerkalender, mit einer Erinnerung am Vortag. Alle 6 Stunden aktualisiert; der Link ist privat, behalte ihn für dich.",
  "Copie ce lien maintenant : il ne sera plus affiché.": "Kopiere diesen Link jetzt: Er wird nicht noch einmal angezeigt.",
  "S'abonner sur cet appareil": "Auf diesem Gerät abonnieren",
