  "{quoi} : indisponible en mode démo (rien ne doit toucher à tes vrais appareils ni à tes vrais accès).": "{quoi}: im Demomodus nicht verfügbar (nichts darf deine echten Geräte oder deine echten Zugänge berühren).",
  "Mode démo actif": "Demomodus aktiv",
  "Données fictives. Touche pour en sortir.": "Fiktive Daten. Tippe, um ihn zu verlassen.",
  "Le mode démo est actif.": "Der Demomodus ist aktiv.",
  "Tout ce que tu vois est fictif : la famille, les comptes, les opérations, les factures, le patrimoine. Tes vraies données restent cachées.": "Alles, was du siehst, ist fiktiv: die Familie, die Konten, die Buchungen, die Rechnungen, das Vermögen. Deine echten Daten bleiben verborgen.",
  "Sortie impossible": "Verlassen nicht möglich",
  "Vérification…": "Überprüfung…",
  "Quitter le mode démo": "Demomodus verlassen",
  "Face ID, Touch ID ou le code de l'appareil est demandé : personne ne peut sortir de la démo à ta place.": "Face ID, Touch ID oder der Gerätecode wird verlangt: Niemand kann die Demo an deiner Stelle verlassen.",
  "Montre Pécule sans rien dévoiler : l'appli passe sur une famille imaginaire, avec ses comptes, ses opérations, ses factures, son patrimoine et son échéancier. Tout fonctionne, l'assistant compris, mais sur ces données fictives.": "Zeig Pécule, ohne etwas preiszugeben: Die App wechselt zu einer erfundenen Familie mit ihren Konten, Buchungen, Rechnungen, ihrem Vermögen und ihrem Terminplan. Alles funktioniert, auch der Assistent, aber mit diesen fiktiven Daten.",
  "Sur cet appareil seulement : les autres membres et tes autres appareils restent sur les vraies données.": "Nur auf diesem Gerät: Die anderen Mitglieder und deine anderen Geräte bleiben bei den echten Daten.",
  "Pour revenir à tes données : Face ID ou Touch ID.": "Zurück zu deinen Daten: Face ID oder Touch ID.",
  "Synchronisation, notifications et clés d'accès sont coupées pendant la démo ; les données fictives sont remises à neuf chaque jour.": "Synchronisierung, Mitteilungen und Passkeys sind während der Demo abgeschaltet; die fiktiven Daten werden jeden Tag neu aufgesetzt.",
  "Mode démo indisponible": "Demomodus nicht verfügbar",
  "Préparation de la démo…": "Demo wird vorbereitet…",
  "Passer en mode démo": "In den Demomodus wechseln",
  "Mode démo non configuré": "Demomodus nicht eingerichtet",
  "Réglage indisponible": "Einstellung nicht verfügbar",
  "Réglage commun à toute la famille. Le fournisseur choisi reçoit tout ce que Pécule confie à l'IA : questions à l'assistant, factures, documents et bulletins de paie. Les clés sont chiffrées et ne sont plus jamais affichées. Un fournisseur est essayé avant d'être choisi ou modifié : si l'essai échoue, rien ne change.": "Einstellung für die ganze Familie. Der gewählte Anbieter erhält alles, was Pécule der KI anvertraut: Fragen an den Assistenten, Rechnungen, Dokumente und Gehaltsabrechnungen. Die Schlüssel werden verschlüsselt und nie wieder angezeigt. Ein Anbieter wird getestet, bevor er gewählt oder geändert wird: Schlägt der Test fehl, ändert sich nichts.",
  "Le mode vocal passe toujours par la ressource Microsoft Foundry.": "Der Sprachmodus läuft immer über die Microsoft-Foundry-Ressource.",
  "Le mode vocal a besoin d'une ressource Microsoft Foundry (son nom et sa clé).": "Der Sprachmodus braucht eine Microsoft-Foundry-Ressource (ihren Namen und ihren Schlüssel).",
  "Utilisé##fournisseur": "In Verwendung",
  "Choisi, incomplet": "Gewählt, unvollständig",
  "Prêt##fournisseur": "Bereit",
