  "L'essai a échoué": "Der Test ist fehlgeschlagen",
  "Essai impossible": "Test nicht möglich",
  "Confier l'IA de Pécule à « {nom} » ? Les questions à l'assistant, les factures, les documents et les bulletins de paie lui seront envoyés.": "Die KI von Pécule „{nom}“ anvertrauen? Fragen an den Assistenten, Rechnungen, Dokumente und Gehaltsabrechnungen werden dorthin gesendet.",
  "{nom} répond maintenant": "{nom} antwortet jetzt",
  "Retirer la clé enregistrée ici ? Celle de l'hébergement reprendra la main, s'il y en a une.": "Den hier gespeicherten Schlüssel entfernen? Der des Hostings übernimmt wieder, falls es einen gibt.",
  "Retirer la clé enregistrée pour ce fournisseur ?": "Den für diesen Anbieter gespeicherten Schlüssel entfernen?",
  "Clé retirée": "Schlüssel entfernt",
  "La clé enregistrée n'est plus lisible (le secret du serveur a changé) : ressaisis-la.": "Der gespeicherte Schlüssel ist nicht mehr lesbar (das Servergeheimnis hat sich geändert): Gib ihn erneut ein.",
  "Une clé est enregistrée. Laisse vide pour la garder.": "Ein Schlüssel ist gespeichert. Leer lassen, um ihn zu behalten.",
  "Clé posée par l'hébergement. En saisir une ici la remplace.": "Schlüssel vom Hosting gesetzt. Gibst du hier einen ein, ersetzt er ihn.",
