  "Ordinateur": "Computer",
  "Autorisation refusée : active les notifications de Pécule dans les réglages de l'appareil.": "Berechtigung verweigert: Aktiviere die Mitteilungen von Pécule in den Geräteeinstellungen.",
  "Notifications activées sur cet appareil": "Mitteilungen auf diesem Gerät aktiviert",
  "Activation impossible": "Aktivierung nicht möglich",
  "Notifications désactivées sur cet appareil": "Mitteilungen auf diesem Gerät deaktiviert",
  "Pour recevoir les notifications sur l'iPhone, installe d'abord Pécule sur l'écran d'accueil (Partager → Sur l'écran d'accueil), puis ouvre l'appli depuis son icône et reviens ici.": "Um Mitteilungen auf dem iPhone zu erhalten, installiere Pécule zuerst auf dem Home-Bildschirm (Teilen → Zum Home-Bildschirm), öffne dann die App über ihr Symbol und komm hierher zurück.",
  "Ce navigateur ne gère pas les notifications.": "Dieser Browser unterstützt keine Mitteilungen.",
  "Reçois sur cet appareil les alertes utiles : opérations à classer, prélèvement nouveau ou inhabituel, solde bas, loyer non reçu, échéances, garanties, enveloppes, et le résumé de la semaine.": "Erhalte auf diesem Gerät die nützlichen Hinweise: zu kategorisierende Buchungen, neue oder ungewöhnliche Lastschrift, niedriger Saldo, nicht eingegangene Miete, Fälligkeiten, Garantien, Budgettöpfe und die Wochenzusammenfassung.",
  "Activer sur cet appareil": "Auf diesem Gerät aktivieren",
  "Notification d'essai envoyée": "Testmitteilung gesendet",
  "Aucun appareil n'a reçu l'essai": "Kein Gerät hat den Test erhalten",
  "Essai": "Test",
  "Désactiver sur cet appareil": "Auf diesem Gerät deaktivieren",
  "Dernières notifications": "Letzte Mitteilungen",
  "Import impossible": "Import nicht möglich",
  "Sur BoursoBank : {lien}, tous les comptes, format CSV. Tu peux redéposer le même fichier : rien n'est compté deux fois, et un nom déjà posé n'est jamais remplacé.": "Bei BoursoBank: {lien}, alle Konten, CSV-Format. Du kannst dieselbe Datei erneut hochladen: Nichts wird doppelt gezählt, und ein bereits vergebener Name wird nie ersetzt.",
  "Pour un prélèvement ou un virement, la synchronisation ne transmet souvent qu'une référence. L'export de BoursoBank porte le nom du créancier : dépose-le ici pour nommer ces opérations et les classer comme celles du même nom.": "Bei einer Lastschrift oder Überweisung liefert die Synchronisierung oft nur eine Referenz. Der Export von BoursoBank enthält den Namen des Gläubigers: Lade ihn hier hoch, um diese Buchungen zu benennen und wie die gleichnamigen zu kategorisieren.",
  "Import en cours…": "Import läuft…",
  "Déposer l'export CSV": "CSV-Export hochladen",
  "Équivalences amusantes": "Lustige Umrechnungen",
  "Pendant un thème, les dépenses se lisent aussi dans l'unité du moment (litres de bière à la Saint-Patrick, kilos de bonbons à Halloween…) et, toute l'année, en temps de travail d'après tes bulletins de paie. Avec, sur l'accueil, « Le chiffre du moment » et ce que coûte la fête en cours. Aucun montant ne change. Valable sur tous tes appareils, assistant compris.": "Während eines Themas lassen sich Ausgaben auch in der Einheit des Moments lesen (Liter Bier am St. Patrick's Day, Kilo Süßigkeiten an Halloween…) und das ganze Jahr über in Arbeitszeit, berechnet aus deinen Gehaltsabrechnungen. Dazu auf der Startseite „Die Zahl des Moments“ und was das laufende Fest kostet. Kein Betrag ändert sich. Gilt auf all deinen Geräten, auch im Assistenten.",
  "En ce moment ({theme}) : {unite}, soit 100 € ≈ {equivalent}.": "Im Moment ({theme}): {unite}, also 100 € ≈ {equivalent}.",
  "En ce moment ({theme}) : {unite}.": "Im Moment ({theme}): {unite}.",
  "Équivalences activées": "Umrechnungen aktiviert",
  "Équivalences désactivées": "Umrechnungen deaktiviert",
  "Logo": "Logo",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment (en ce moment : {theme}).": "Die Truhe für jeden Tag, auf dem Hintergrund deiner Wahl. In der App und im Browser-Tab übernimmt sie von selbst die Dekoration des aktuellen Themas (im Moment: {theme}).",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment.": "Die Truhe für jeden Tag, auf dem Hintergrund deiner Wahl. In der App und im Browser-Tab übernimmt sie von selbst die Dekoration des aktuellen Themas.",
  "Icône sur l'écran d'accueil": "Symbol auf dem Home-Bildschirm",
  "Comme le logo": "Wie das Logo",
  "L'iPhone garde l'icône du jour où Pécule a été ajouté à l'écran d'accueil : elle ne peut pas changer toute seule. Pour en changer, ouvre Pécule dans Safari, choisis l'icône ici, supprime l'ancienne de l'écran d'accueil, puis Partager → « Sur l'écran d'accueil ». Il faudra te reconnecter et réactiver les notifications.": "Das iPhone behält das Symbol des Tages, an dem Pécule zum Home-Bildschirm hinzugefügt wurde: Es kann sich nicht von selbst ändern. Um es zu ändern, öffne Pécule in Safari, wähle hier das Symbol, lösche das alte vom Home-Bildschirm und dann Teilen → „Zum Home-Bildschirm“. Du musst dich neu anmelden und die Mitteilungen wieder aktivieren.",
  "Tu es dans l'appli installée : fais ce choix depuis Safari, c'est lui qui crée l'icône.": "Du bist in der installierten App: Triff diese Wahl in Safari, denn Safari erstellt das Symbol.",
