  "Finta se branche par la variable FINTA_API_KEY de l'hébergement. Un compte que tu as rattaché à Enable Banking n'est plus alimenté par Finta.": "Finta wird über die Variable FINTA_API_KEY des Hostings angebunden. Ein Konto, das du mit Enable Banking verknüpft hast, wird nicht mehr von Finta gespeist.",
