  "foyer pays devise monnaie fuseau horaire ecrans affiches modules personnes enfant banques professionnelles": "haushalt land währung geld zeitzone bildschirme angezeigt module personen kind geschäftsbanken",
  "Devise": "Währung",
  "Les unités des thèmes ont un prix fixé en euros : dans une autre devise, seule l'équivalence en temps de travail s'affiche.": "Die Einheiten der Themen haben einen Preis in Euro: In einer anderen Währung wird nur die Entsprechung in Arbeitszeit angezeigt.",
  "Pays enregistré. Les écrans Impôts et Retraite, qui lisent des documents français, sont retirés : tu peux les remettre plus bas.": "Land gespeichert. Die Bildschirme Steuern und Rente, die französische Dokumente lesen, wurden entfernt: Du kannst sie weiter unten wieder einblenden.",
  "Pays enregistré": "Land gespeichert",
  "Aucune opération n'est encore enregistrée : seul l'affichage change.": "Es ist noch keine Buchung gespeichert: Nur die Anzeige ändert sich.",
  "Passer la devise du foyer de {avant} à {apres} ?": "Die Währung des Haushalts von {avant} auf {apres} umstellen?",
  "Les montants saisis à la main (budgets, objectifs, placements, biens, crédits, bulletins) gardent leur chiffre : à revoir ensuite.": "Von Hand eingegebene Beträge (Budgets, Ziele, Anlagen, Immobilien, Kredite, Gehaltsabrechnungen) behalten ihre Zahl: danach bitte prüfen.",
  "Devise du foyer enregistrée": "Währung des Haushalts gespeichert",
  "Pays et devise": "Land und Währung",
  "Devise du foyer": "Währung des Haushalts",
  "Celle de tous les totaux, des budgets et du patrimoine.": "Die Währung aller Summen, der Budgets und des Vermögens.",
  "Fuseau horaire": "Zeitzone",
  "Il dit quel jour on est : échéances, notifications, résumé du lundi.": "Sie bestimmt, welcher Tag heute ist: Fälligkeiten, Benachrichtigungen, Montagsübersicht.",
  "Fuseau horaire enregistré": "Zeitzone gespeichert",
  "Un compte tenu dans une autre devise garde ses montants d'origine ; ils sont convertis au cours de référence de la Banque centrale européenne du jour de chaque opération. Le calendrier fiscal et certaines fêtes ne valent qu'en France.": "Ein Konto in einer anderen Währung behält seine ursprünglichen Beträge; sie werden zum Referenzkurs der Europäischen Zentralbank vom Tag jeder Buchung umgerechnet. Der Steuerkalender und einige Feste gelten nur in Frankreich.",
  "Passer ce compte en {devise} ? Ses montants et son solde, tels qu'ils ont été saisis, seront lus dans cette devise.": "Dieses Konto auf {devise} umstellen? Seine Beträge und sein Saldo werden, so wie sie eingegeben wurden, in dieser Währung gelesen.",
