  "Service tiers sur abonnement : Pécule le lit si tu as déjà un compte Finta et sa clé d'API. Rien ne t'oblige à le prendre.": "Kostenpflichtiger Dienst eines Drittanbieters: Pécule liest ihn aus, wenn du schon ein Finta-Konto und dessen API-Schlüssel hast. Du musst ihn nicht nehmen.",
  "Sans rien relier : tu déposes de temps en temps l'export OFX, QIF ou CSV de ton espace client.": "Ohne etwas zu verbinden: Du legst ab und zu den OFX-, QIF- oder CSV-Export aus deinem Onlinebanking ab.",
