  "PDF ou photo : le fichier est rangé tout de suite. L'import d'un dossier entier, avec lecture des données, n'est pas proposé en mode démo.": "PDF oder Foto: Die Datei wird sofort abgelegt. Der Import eines ganzen Ordners mit Auslesen der Daten wird im Demomodus nicht angeboten.",
  "PDF, photos, exports de la banque : chaque fichier est rangé, et Pécule lit ceux qu'il reconnaît (bulletins de paie, avis d'impôt, relevés, contrats, factures) pour te proposer leurs données. Rien n'est écrit sans ta validation.": "PDFs, Fotos, Exporte der Bank: Jede Datei wird abgelegt, und Pécule liest die, die es erkennt (Gehaltsabrechnungen, Steuerbescheide, Auszüge, Verträge, Rechnungen), um dir ihre Daten vorzuschlagen. Nichts wird ohne deine Bestätigung geschrieben.",
