  "Gratuit pour un usage personnel : tu crées ton application sur enablebanking.com et tu y relies les comptes à ton nom (un autre adulte du foyer fait de même pour les siens). Lecture seule, directement chez la banque.": "Für den privaten Gebrauch kostenlos: Du legst deine Anwendung auf enablebanking.com an und verbindest dort die Konten auf deinen Namen (ein weiterer Erwachsener im Haushalt macht dasselbe für seine). Nur Lesen, direkt bei der Bank.",
