  "En gris à droite du jour : ses petits achats · clic sur un jour : ses opérations": "Grau neben dem Tag: seine kleinen Einkäufe · Klick auf einen Tag: seine Buchungen",
  "Le calendrier du mois": "Der Monatskalender",
