  "Rien ce jour-là.": "Nichts an diesem Tag.",
  "Ce que tu possèdes (comptes, épargne, biens, crypto) moins ce que tu dois encore. Les biens et les crédits communs comptent pour ta part.": "Was du besitzt (Konten, Erspartes, Immobilien, Krypto) minus das, was du noch schuldest. Gemeinsame Güter und Kredite zählen mit deinem Anteil.",
  "Ce qu'il y a sur tes comptes aujourd'hui. Les achats par carte à débit différé pas encore prélevés n'en sont pas déduits.": "Was heute auf deinen Konten liegt. Noch nicht abgebuchte Käufe mit Karten mit verzögerter Abbuchung sind nicht abgezogen.",
  "Revenus du mois moins dépenses du mois. Les mouvements entre tes comptes et les versements d'épargne ne comptent pas.": "Einnahmen des Monats minus Ausgaben des Monats. Umbuchungen zwischen deinen Konten und Sparbeträge zählen nicht.",
