  "Passerait à {montant} le {date}.": "Würde am {date} auf {montant} fallen.",
  "Surveiller mes soldes": "Meine Kontostände überwachen",
  "Pécule te prévient quand un compte est sous son seuil, ou va y passer.": "Pécule warnt dich, wenn ein Konto unter seiner Schwelle liegt oder bald darunter fällt.",
  "Seuil": "Schwelle",
  "En dessous de ce montant, un compte est signalé. Un montant négatif prévient avant la limite d'un découvert autorisé.": "Unter diesem Betrag wird ein Konto gemeldet. Ein negativer Betrag warnt vor dem Limit eines eingeräumten Dispos.",
  "Me prévenir": "Mich warnen",
  "Combien de jours avant que le compte passe sous le seuil (j = jours).": "Wie viele Tage, bevor das Konto unter die Schwelle fällt (j = Tage).",
  "{n} j": "{n} j",
  "Comptes surveillés — décoche un compte pour l'écarter, ou donne-lui un seuil à lui (vide : le seuil ci-dessus).": "Überwachte Konten — entferne das Häkchen, um ein Konto auszunehmen, oder gib ihm eine eigene Schwelle (leer: die Schwelle oben).",
  "Comment c'est calculé : le solde du jour, puis ce qui est attendu sur ce compte d'ici là, en entrées comme en sorties — ce qui y revient chaque mois (prélèvements, virements, salaire) et le relevé d'une carte à débit différé. Les achats du quotidien ne sont pas devinés : c'est une estimation, à lire comme « au mieux ». L'alerte arrive en notification si « Solde bas » est activé sur l'appareil, et se lit aussi sur le calendrier du mois et le tableau de bord. Tu peux demander à l'assistant de changer ces réglages.": "So wird gerechnet: der heutige Kontostand, dann das, was bis dahin auf diesem Konto erwartet wird, Eingänge wie Ausgänge — was jeden Monat wiederkehrt (Lastschriften, Überweisungen, Gehalt) und die Abrechnung einer Karte mit verzögerter Abbuchung. Alltagseinkäufe werden nicht geraten: Es ist eine Schätzung, zu lesen als „bestenfalls“. Die Warnung kommt als Mitteilung, wenn „Niedriger Kontostand“ auf dem Gerät aktiviert ist, und steht auch im Monatskalender und in der Übersicht. Du kannst den Assistenten bitten, diese Einstellungen zu ändern.",
  "{compte} est sous son seuil : {montant}.": "{compte} liegt unter seiner Schwelle: {montant}.",
  "{compte} passerait à {montant} le {date}, après {cause}.": "{compte} würde am {date} auf {montant} fallen, nach {cause}.",
  "{compte} passerait à {montant} le {date}.": "{compte} würde am {date} auf {montant} fallen.",
  "Régler l'alerte de solde bas": "Warnung bei niedrigem Kontostand einstellen",
  "Solde bas": "Niedriger Kontostand",
  "Solde bas, alertes de cet appareil, ouverture instantanée": "Niedriger Kontostand, Warnungen dieses Geräts, sofortiges Öffnen",
  "Relevé de la carte {nom}": "Abrechnung der Karte {nom}",
  "Solde bas, aujourd'hui ou à venir": "Niedriger Kontostand, heute oder bald",
  "Solde bas à venir : {montant} le {date}": "Niedriger Kontostand voraus: {montant} am {date}",
  "{compte} — après {cause} ({montant}).": "{compte} — nach {cause} ({montant}).",
